CREATE OR REPLACE FUNCTION platform.staff_observed_time()
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  guard bigint := hashtextextended('staff-clock-v1', 0);
  sample timestamptz;
  micros bigint;
  floor_us bigint; BEGIN
  PERFORM pg_advisory_lock(guard); BEGIN
    sample := clock_timestamp();
    micros := (extract(epoch FROM sample) * 1000000)::bigint;
    SELECT last_value INTO floor_us FROM north_star_internal.staff_clock_microseconds;
    IF micros < floor_us THEN
      sample := NULL;
    ELSE
      PERFORM setval('north_star_internal.staff_clock_microseconds', micros); END IF;
  EXCEPTION WHEN query_canceled OR OTHERS THEN
    PERFORM pg_advisory_unlock(guard);
    RAISE; END;
  PERFORM pg_advisory_unlock(guard);
  RETURN sample; END $function$

CREATE OR REPLACE FUNCTION platform.staff_session_principal(t uuid, e uuid, handle bytea, protected_write boolean, foreground boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE p uuid; s platform.staff_sessions%ROWTYPE; observed timestamptz; BEGIN
  SELECT principal_id INTO p FROM platform.staff_sessions
    WHERE tenant_id=t AND environment_id=e AND application_digest=handle;
  IF protected_write THEN
    PERFORM 1 FROM platform.staff_accounts WHERE tenant_id=t AND environment_id=e AND principal_id=p
      AND status='active' FOR SHARE;
  ELSE
    PERFORM 1 FROM platform.staff_accounts WHERE tenant_id=t AND environment_id=e AND principal_id=p
      AND status='active'; END IF;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF protected_write THEN
    SELECT * INTO s FROM platform.staff_sessions WHERE tenant_id=t AND environment_id=e AND application_digest=handle FOR UPDATE;
  ELSE
    SELECT * INTO s FROM platform.staff_sessions WHERE tenant_id=t AND environment_id=e AND application_digest=handle; END IF;
  observed := platform.staff_observed_time();
  IF NOT FOUND OR s.revoked_at IS NOT NULL OR observed IS NULL OR observed < s.last_activity
      OR observed >= LEAST(s.absolute_deadline,s.last_activity + interval '30 minutes')
      OR NOT EXISTS (SELECT FROM platform.current_policy_memberships m JOIN platform.current_policy_roles r
        USING(tenant_id,environment_id,role_id) WHERE m.tenant_id=t AND m.environment_id=e
        AND m.principal_id=p AND m.revoked_at IS NULL AND r.revoked_at IS NULL) THEN RETURN NULL; END IF;
  IF protected_write AND foreground AND observed >= s.last_activity + interval '1 minute' THEN
    UPDATE platform.staff_sessions SET last_activity=observed WHERE family_id=s.family_id; END IF;
  RETURN p; END $function$

CREATE OR REPLACE FUNCTION platform.stage_document_upload(scope text, entity text, record_key uuid, upload uuid, field text, category text, filename text, mime text, payload bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$ DECLARE
  i record; s platform.document_upload_staging; fields jsonb; receipt jsonb;
  hash text := encode(sha256(payload), 'hex'); BEGIN
  SELECT * INTO i FROM platform.document_identity();
  fields := platform.document_fields(scope, entity, 'upload');
  IF fields IS NULL OR (field IS NOT NULL AND NOT fields @> jsonb_build_array(jsonb_build_object('fieldId',field))) THEN
    RAISE EXCEPTION 'Unavailable file field' USING ERRCODE = 'D0404'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('documents:' || i.tenant_id || ':' || i.environment_id, 0));
  SELECT * INTO s FROM platform.document_upload_staging
    WHERE (tenant_id,environment_id,upload_id) = (i.tenant_id,i.environment_id,upload);
  IF FOUND THEN
    IF (s.principal_id,s.owner_scope,s.entity_id,s.record_id,s.field_id,s.category_id,s.file_name,s.digest,s.content_type)
       IS DISTINCT FROM (i.principal_id,scope,entity,record_key,field,category,filename,hash,mime) THEN
      RAISE EXCEPTION 'This upload ID already has different input.' USING ERRCODE = 'D0409'; END IF;
    SELECT platform.document_metadata(v,b.content_type,b.byte_length) INTO receipt FROM platform.document_versions v
      JOIN platform.document_blobs b USING (tenant_id,environment_id,owner_scope,digest)
      WHERE (v.tenant_id,v.environment_id,v.upload_id) = (i.tenant_id,i.environment_id,upload);
    IF FOUND THEN RETURN receipt; END IF;
    IF s.scan_clean IS FALSE THEN RAISE EXCEPTION 'The file did not pass content screening.' USING ERRCODE = 'D0422'; END IF;
    IF s.retired_at IS NOT NULL OR s.expires_at <= clock_timestamp() THEN
      RAISE EXCEPTION 'This staged upload expired.' USING ERRCODE = 'D0409'; END IF;
    RETURN NULL; END IF;
  PERFORM platform.retire_document_upload_staging(NULL);
  IF (SELECT coalesce(sum(byte_length),0) FROM platform.document_upload_staging
      WHERE (tenant_id,environment_id) = (i.tenant_id,i.environment_id)) + octet_length(payload) > 41943040 THEN
    RAISE EXCEPTION 'The upload staging quota is full.' USING ERRCODE = 'D0413'; END IF;
  INSERT INTO platform.document_upload_staging (tenant_id,environment_id,upload_id,principal_id,owner_scope,
    entity_id,record_id,field_id,category_id,file_name,content_type,digest,bytes)
  VALUES (i.tenant_id,i.environment_id,upload,i.principal_id,scope,entity,record_key,field,category,filename,mime,hash,payload);
  RETURN NULL; END $function$

CREATE OR REPLACE FUNCTION platform.workflow_decide_approval(requested_run uuid, requested_cursor integer, requested_fence bigint, requested_plan_digest text, decision text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  tenant uuid := nullif(current_setting('north_star.tenant_id', true), '')::uuid;
  environment uuid := nullif(current_setting('north_star.environment_id', true), '')::uuid;
  principal uuid := nullif(current_setting('north_star.principal_id', true), '')::uuid;
  active_pointer uuid;
  active_release uuid; BEGIN
  IF decision NOT IN ('APPROVED', 'DECLINED') OR decision IS NULL OR principal IS NULL
     OR nullif(current_setting('north_star.request_id', true), '') IS NULL
  THEN RETURN false; END IF;
  PERFORM 1 FROM platform.release_activation_authority_epochs AS epoch WHERE epoch.tenant_id = tenant FOR SHARE;
  SELECT p.pointer_id, p.release_id INTO active_pointer, active_release
    FROM platform.active_release_pointers AS p
   WHERE p.tenant_id = tenant AND p.environment_id = environment AND p.fence = requested_fence
   FOR SHARE;
  IF NOT FOUND THEN RETURN false; END IF;
  PERFORM platform.lock_current_policy_epoch(tenant, environment);
  PERFORM 1 FROM platform.workflow_runs AS r
   WHERE r.tenant_id = tenant AND r.environment_id = environment AND r.run_id = requested_run
     AND r.pointer_id = active_pointer AND r.release_id = active_release
     AND r.execution_fence = requested_fence AND r.status = 'WAITING'
   FOR UPDATE;
  IF NOT FOUND OR NOT EXISTS (
    SELECT 1 FROM platform.workflow_approval_worklist(requested_run) AS candidate
     WHERE candidate.cursor = requested_cursor AND candidate.fence = requested_fence
       AND candidate.plan_digest = requested_plan_digest
  ) THEN RETURN false; END IF;
  UPDATE platform.workflow_pending_approvals AS a
     SET status = decision, decided_by = principal, decided_at = clock_timestamp(),
         decision_request_id = current_setting('north_star.request_id')::uuid
   WHERE a.tenant_id = tenant AND a.environment_id = environment AND a.run_id = requested_run
     AND a.cursor = requested_cursor AND a.fence = requested_fence
     AND a.plan_digest = requested_plan_digest AND a.status = 'PENDING';
  IF NOT FOUND THEN RETURN false; END IF;
  -- The run lock serializes the decision with journal completion and wakeup.
  INSERT INTO platform.workflow_journal (tenant_id, environment_id, run_id, cursor, kind, canonical_bytes)
  SELECT tenant, environment, requested_run, requested_cursor, 'RESULT',
         convert_to((decision = 'APPROVED')::text, 'UTF8')
   WHERE NOT EXISTS (
     SELECT 1 FROM platform.workflow_journal AS j
      WHERE (j.tenant_id, j.environment_id, j.run_id, j.cursor, j.kind) =
            (tenant, environment, requested_run, requested_cursor, 'RESULT')
   );
  UPDATE platform.workflow_runs SET status = 'RUNNABLE', reason = NULL
   WHERE tenant_id = tenant AND environment_id = environment AND run_id = requested_run;
  RETURN true; END
$function$

